<?php
defined('BASEPATH') or exit('No direct script access allowed');
class Pipeline_operator_company extends CI_Controller {
 public function __construct(){parent::__construct();is_login();$this->load->library('Pipeline_access');$this->pipeline_access->require_menu('operator_company');$this->load->model('Pipeline_operator_company_model','company');if(!$this->session->userdata('pipeline_form_token'))$this->session->set_userdata('pipeline_form_token',bin2hex(random_bytes(24)));}
 public function index(){ $areas=$this->company->billing->branches();$raw=$this->input->method()==='post'?$this->input->post('SpbbID'):$this->input->get('area');if($raw!==null&&(!is_string($raw)||!ctype_digit($raw)))show_error('Area tidak valid.',422);$area=$raw!==null?(int)$raw:(int)($areas[0]['SpbbID']??0);$error='';$form=array();if($area){try{$form=$this->company->row($area)?:array();}catch(Exception $e){show_error($e->getMessage(),403);}}
  if($this->input->method()==='post'){$token=$this->input->post('pipeline_token');if(!is_string($token)||!hash_equals($this->session->userdata('pipeline_form_token'),$token))show_error('Form kedaluwarsa.',403);try{$this->company->save($area,$this->input->post(),$_FILES);$this->session->set_flashdata('Berhasil','Identitas perusahaan disimpan.');redirect('Pipeline_operator_company?area='.$area);return;}catch(Exception $e){$error=$e->getMessage();}}
  $data=compact('areas','area','form','error');$data['judul']='Profil Perusahaan Operator';$data['pipeline_token']=$this->session->userdata('pipeline_form_token');$this->load->view('templates/header',$data);$this->load->view('templates/sidebar');$this->load->view('pipeline/operator_company',$data);$this->load->view('templates/footer');
 }
 public function file($area,$kind){if(!in_array($kind,array('Logo','Identity'),true))show_404();try{$row=$this->company->row((int)$area);}catch(Exception $e){show_error('Area di luar akses.',403);}if(!$row||empty($row[$kind.'StoredName']))show_404();$name=$row[$kind.'StoredName'];if(!preg_match('/^[a-f0-9]{48}\.(jpg|png|pdf)$/D',$name))show_404();$path=APPPATH.'storage/operator_company/'.$name;if(!is_file($path))show_404();$this->output->set_header('Cache-Control: private, no-store')->set_header('X-Content-Type-Options: nosniff')->set_header('Content-Disposition: inline; filename="'.$kind.'.'.pathinfo($name,PATHINFO_EXTENSION).'"')->set_content_type($row[$kind.'Mime'])->set_output(file_get_contents($path));}
}
